// Node 7 - Validate & Enforce Safety (actions/ETF/crypto only)

function isObj(x) { return x && typeof x === "object" && !Array.isArray(x); }
function safeJsonParse(s) { try { return JSON.parse(s); } catch { return null; } }
function toNumOrNull(x) { const n = Number(x); return Number.isFinite(n) ? n : null; }
function toNum(x, dflt = 0) { const n = Number(x); return Number.isFinite(n) ? n : dflt; }
function normSymbol(v) { return String(v ?? "").trim().toUpperCase(); }

function normAssetClass(v) {
  const raw = String(v ?? "").trim().toUpperCase();
  if (raw === "CRYPTO") return "CRYPTO";
  if (raw === "ETF") return "ETF";
  return "EQUITY";
}

function deepClone(obj) { try { return JSON.parse(JSON.stringify(obj)); } catch { return obj; } }

function extractAgentDecisionObject(input) {
  let decisionRaw = null;

  if (isObj(input.output) && Array.isArray(input.output.actions)) return { ...input.output, _parseStatus: "OK_OBJECT_OUTPUT" };
  if (isObj(input.agentDecision)) return { ...input.agentDecision, _parseStatus: "OK_AGENTDECISION" };
  if (Array.isArray(input.output) && input.output.length > 0 && input.output.every((x) => isObj(x) && String(x.action ?? "").length)) {
    return { actions: input.output, dataCaveats: [], backfillRequests: [], _parseStatus: "OK_ACTIONS_ARRAY_OUTPUT" };
  }

  if (typeof input.output === "string") decisionRaw = input.output;
  else if (input.output?.text) decisionRaw = input.output.text;
  else if (Array.isArray(input.output) && input.output[0]?.content?.[0]?.text) decisionRaw = input.output[0].content[0].text;
  else if (input.text) decisionRaw = input.text;

  if (typeof decisionRaw === "string") {
    let cleaned = decisionRaw.trim();
    if (cleaned.includes("```")) {
      const parts = cleaned.split("```");
      if (parts.length >= 3) {
        cleaned = parts[1];
        if (cleaned.toLowerCase().startsWith("json")) cleaned = cleaned.substring(4).trim();
      }
    }
    const firstBrace = cleaned.indexOf("{");
    const lastBrace = cleaned.lastIndexOf("}");
    if (firstBrace !== -1 && lastBrace !== -1) cleaned = cleaned.substring(firstBrace, lastBrace + 1);

    const parsed = safeJsonParse(cleaned);
    if (isObj(parsed)) return { ...parsed, _parseStatus: "OK_CLEANED_JSON" };
    return { _rawText: decisionRaw, _parseStatus: "TEXT_NOT_JSON" };
  }

  return { _parseStatus: "MISSING_DECISION", _why: "No decision payload found." };
}

function coerceAgentDecisionToExpectedShape(agentDecision) {
  if (!isObj(agentDecision)) return { _parseStatus: "NOT_OBJECT", actions: [], dataCaveats: [], backfillRequests: [] };
  const d = deepClone(agentDecision);
  if (!Array.isArray(d.actions)) d.actions = [];
  if (!Array.isArray(d.dataCaveats)) d.dataCaveats = [];
  if (!Array.isArray(d.backfillRequests)) d.backfillRequests = [];
  return d;
}

function normalizeOrderType(v) {
  const s = String(v ?? "").trim().toUpperCase();
  if (s === "LMT" || s === "LIMIT") return "LIMIT";
  if (s === "MKT" || s === "MARKET") return "MARKET";
  return s || "MARKET";
}

function inferQtyFromWeightPct(portfolioSummary, weightPct, priceHint) {
  const tv = toNum(portfolioSummary?.totalPortfolioValueEUR, 0);
  const w = toNumOrNull(weightPct);
  const px = toNumOrNull(priceHint);
  if (!tv || !w || !px || px <= 0) return null;
  const eur = tv * (w / 100.0);
  const q = Math.floor(eur / px);
  return Number.isFinite(q) && q > 0 ? q : null;
}

const input = $json ?? {};
const transfer_pack = input.transfer_pack || {};
const final_db_path = transfer_pack.db_path || input.db_path || "";

const portfolioSummary =
  input.portfolioSummary ??
  input.ctx?.portfolioSummary ??
  transfer_pack.portfolioSummary ??
  { cashEUR: 0, totalPortfolioValueEUR: null, positions: [] };

const configRaw = input.config ?? input.ctx?.config ?? transfer_pack.config ?? {};
const ts = new Date().toISOString();
const runId = String(input?.run?.runId ?? input?.runId ?? transfer_pack?.run?.runId ?? "").trim() || `RUN_${Date.now()}`;
const model = String(input?.run?.model ?? transfer_pack?.run?.model ?? "UNKNOWN").trim();

let agentDecision = extractAgentDecisionObject(input);
agentDecision = coerceAgentDecisionToExpectedShape(agentDecision);

const execSet = new Set(["OPEN", "INCREASE", "DECREASE", "CLOSE"]);
const posList = portfolioSummary?.positions || [];
const posQty = {};
const posLast = {};
for (const p of posList) {
  const s = normSymbol(p.Symbol || p.symbol);
  if (!s || s === "CASH_EUR") continue;
  posQty[s] = toNum(p.Quantity ?? p.quantity, 0);
  posLast[s] = toNumOrNull(p.LastPrice ?? p.lastPrice ?? p.price);
}

const orders = [];
const warnings = [];

for (const a of agentDecision.actions || []) {
  const action = String(a.action || "").toUpperCase();
  if (!execSet.has(action)) continue;

  const symbol = normSymbol(a.symbol_internal || a.symbol);
  if (!symbol || symbol === "CASH_EUR") { warnings.push("ORDER_SKIP:NO_SYMBOL"); continue; }
  if (String(a.symbol_yahoo || "").toUpperCase().endsWith("=X") || symbol.startsWith("F" + "X:")) {
    warnings.push(`ORDER_SKIP:UNSUPPORTED_ASSET:${symbol}`);
    continue;
  }

  const assetClass = normAssetClass(a.assetClass);
  const currentQty = toNum(posQty[symbol], 0);
  const limitPx = toNumOrNull(a.entryPlan?.limitPrice);
  const lastPx = toNumOrNull(posLast[symbol]);
  const priceHint = limitPx ?? lastPx;
  let qty = null;

  if (action === "CLOSE") {
    qty = currentQty;
  } else if (action === "DECREASE") {
    const targetFinal = toNumOrNull(a.targetQty);
    if (targetFinal === null) { warnings.push(`ORDER_SKIP:DECREASE_NO_TARGETQTY:${symbol}`); continue; }
    qty = Math.max(0, currentQty - targetFinal);
  } else if (action === "INCREASE") {
    const targetFinal = toNumOrNull(a.targetQty);
    if (targetFinal === null) { warnings.push(`ORDER_SKIP:INCREASE_NO_TARGETQTY:${symbol}`); continue; }
    if (currentQty <= 0) {
      qty = Math.max(0, targetFinal);
      if (qty > 0) a.__normalized_action = "OPEN";
    } else {
      qty = Math.max(0, targetFinal - currentQty);
    }
  } else if (action === "OPEN") {
    const tq = toNumOrNull(a.targetQty);
    qty = tq !== null && tq > 0 ? tq : inferQtyFromWeightPct(portfolioSummary, a.targetWeightPct, priceHint);
  }

  if (!qty || qty <= 0) { warnings.push(`ORDER_SKIP:QTY_NONPOSITIVE:${symbol}:${action}`); continue; }

  const effectiveAction = a.__normalized_action || action;
  const side = effectiveAction === "OPEN" || effectiveAction === "INCREASE" ? "BUY" : "SELL";
  const orderType = normalizeOrderType(a.entryPlan?.orderType);

  orders.push({
    symbol,
    action: effectiveAction,
    side,
    quantity: qty,
    assetClass,
    orderType,
    limitPrice: orderType === "LIMIT" ? limitPx : null,
  });
}

let availableCash = toNum(portfolioSummary?.cashEUR, 0);
for (const o of orders) {
  if (o.side !== "SELL") continue;
  const sellPx = (normalizeOrderType(o.orderType) === "LIMIT" ? toNumOrNull(o.limitPrice) : null) ?? toNumOrNull(posLast[o.symbol]) ?? 0;
  availableCash += toNum(o.quantity, 0) * sellPx;
}

const cashSafeOrders = [];
for (const o of orders) {
  if (o.side === "SELL") {
    cashSafeOrders.push(o);
    continue;
  }

  const buyPx = (normalizeOrderType(o.orderType) === "LIMIT" ? toNumOrNull(o.limitPrice) : null) ?? toNumOrNull(posLast[o.symbol]);
  if (!buyPx || buyPx <= 0) {
    warnings.push(`ORDER_SKIP:NO_BUY_PRICE:${o.symbol}`);
    continue;
  }

  const requestedQty = toNum(o.quantity, 0);
  const affordableQty = Math.floor((availableCash + 1e-9) / buyPx);
  if (affordableQty <= 0) {
    warnings.push(`ORDER_SKIP:INSUFFICIENT_CASH:${o.symbol}:need=${(requestedQty * buyPx).toFixed(2)}:avail=${availableCash.toFixed(2)}`);
    continue;
  }
  if (affordableQty < requestedQty) {
    warnings.push(`ORDER_RESIZED:CASH_CAP:${o.symbol}:from=${requestedQty}:to=${affordableQty}`);
    o.quantity = affordableQty;
  }
  availableCash -= toNum(o.quantity, 0) * buyPx;
  cashSafeOrders.push(o);
}

orders.length = 0;
orders.push(...cashSafeOrders);

const decision = orders.length ? "TRADE" : "NO_TRADE";
if (agentDecision?._parseStatus && !String(agentDecision._parseStatus).startsWith("OK")) {
  warnings.push(`AGENT_DECISION_PARSE:${agentDecision._parseStatus}`);
}

const ctx = {
  meta: input.meta ?? transfer_pack.meta ?? {},
  config: configRaw,
  run: { runId, timestampParis: ts, model },
  portfolioSummary,
};

return [{
  json: {
    decision,
    commentary: `Decision: ${decision} | Orders: ${orders.length} | Actions: ${(agentDecision.actions || []).length}`,
    agentDecision,
    orders,
    metrics: {},
    warnings,
    ctx,
    portfolioSummary,
    transfer_pack,
    db_path: final_db_path,
  },
}];

function normalizeDbPath(v) {
  const s = String(v ?? "").trim().replace(/\\/g, "/");
  return s.replace("/local-files/", "/files/");
}

function toNum(v, dflt = null) {
  const n = Number(v);
  return Number.isFinite(n) ? n : dflt;
}

function clampText(v, max = 0) {
  const s = String(v ?? "").replace(/\s+/g, " ").trim();
  return max > 0 ? s.slice(0, max) : s;
}

function mapActionToSignal(action) {
  const a = String(action || "").toUpperCase();
  if (["OPEN", "INCREASE", "BUY"].includes(a)) return "BUY";
  if (["DECREASE", "CLOSE", "SELL"].includes(a)) return "SELL";
  if (a === "WATCH") return "WATCH";
  if (a === "HOLD") return "HOLD";
  if (a === "PROPOSE_OPEN") return "PROPOSE_OPEN";
  if (a === "PROPOSE_CLOSE") return "PROPOSE_CLOSE";
  return "NEUTRAL";
}

function normalizeOrderType(v) {
  const s = String(v ?? "").trim().toUpperCase();
  if (s === "LMT" || s === "LIMIT") return "LIMIT";
  if (s === "MKT" || s === "MARKET") return "MARKET";
  return s || "MARKET";
}

function extractSymbolFromText(text) {
  const m = String(text || "").toUpperCase().match(/\bFX:[A-Z]{6}\b|\b[A-Z0-9]{1,10}(?:\.[A-Z]{1,4})?\b/);
  return m ? m[0] : "GLOBAL";
}

function roundTo(v, digits = 2) {
  const n = Number(v);
  if (!Number.isFinite(n)) return 0;
  const factor = 10 ** digits;
  return Math.round(n * factor) / factor;
}

function normalizeSymbol(v) {
  return String(v ?? "").trim();
}

function inferRiskStatus(cashPct, cashEUR) {
  if (Number.isFinite(cashEUR) && cashEUR < -0.01) return "RISK_OFF";
  if (Number.isFinite(cashPct) && cashPct >= 0.8) return "DEFENSIVE";
  if (Number.isFinite(cashPct) && cashPct <= 0.1) return "RISK_ON";
  return "BALANCED";
}

function buildSnapshotsFromPortfolio(portfolioSummary, orders, priceMap, ts, meta) {
  const positionsIn = Array.isArray(portfolioSummary?.positions) ? portfolioSummary.positions : [];
  const positionsValueInput = positionsIn.reduce((sum, row) => {
    const marketValue = toNum(row?.MarketValue, null);
    if (marketValue !== null) return sum + marketValue;
    return sum + (toNum(row?.Quantity, 0) * toNum(row?.LastPrice, 0));
  }, 0);
  const summaryCash = toNum(portfolioSummary?.cashEUR, null);
  const summaryTotal = toNum(portfolioSummary?.totalPortfolioValueEUR, null);
  let startCash = summaryCash;
  if (
    summaryTotal !== null
    && Number.isFinite(positionsValueInput)
    && Math.abs(((summaryCash ?? 0) + positionsValueInput) - summaryTotal) > 0.01
  ) {
    const reconciledCash = summaryTotal - positionsValueInput;
    if (Number.isFinite(reconciledCash)) startCash = reconciledCash;
  }
  if (!Number.isFinite(startCash)) startCash = 0;
  const posMap = new Map();

  for (const row of positionsIn) {
    const symbol = normalizeSymbol(row?.Symbol);
    const qty = toNum(row?.Quantity, 0);
    if (!symbol || qty <= 0) continue;
    posMap.set(symbol, {
      symbol,
      qty,
      avgCost: toNum(row?.AvgPrice, toNum(row?.LastPrice, 0) || 0),
      lastPrice: toNum(row?.LastPrice, toNum(row?.AvgPrice, 0) || 0),
      assetClass: String(row?.AssetClass || "EQUITY").trim().toUpperCase() || "EQUITY",
      sector: clampText(row?.Sector || "UNKNOWN", 128) || "UNKNOWN",
    });
  }

  let cashEUR = startCash;
  for (const order of orders || []) {
    const symbol = normalizeSymbol(order?.symbol);
    const side = String(order?.side || "").trim().toUpperCase();
    const qty = toNum(order?.quantity, 0);
    const orderType = normalizeOrderType(order?.orderType);
    const price =
      (orderType === "LIMIT" ? toNum(order?.limitPrice, null) : null) ??
      toNum(priceMap[symbol], null);

    if (!symbol || qty <= 0 || !Number.isFinite(price) || price <= 0) continue;

    if (side === "BUY") {
      const current = posMap.get(symbol) || {
        symbol,
        qty: 0,
        avgCost: price,
        lastPrice: price,
        assetClass: String(order?.assetClass || "EQUITY").trim().toUpperCase() || "EQUITY",
        sector: "UNKNOWN",
      };
      const newQty = current.qty + qty;
      current.avgCost = newQty > 0 ? (((current.qty * current.avgCost) + (qty * price)) / newQty) : price;
      current.qty = newQty;
      current.lastPrice = toNum(priceMap[symbol], price);
      posMap.set(symbol, current);
      cashEUR -= qty * price;
      continue;
    }

    if (side === "SELL") {
      const current = posMap.get(symbol);
      if (!current) continue;
      const execQty = Math.min(qty, current.qty);
      if (execQty <= 0) continue;
      current.qty -= execQty;
      current.lastPrice = toNum(priceMap[symbol], price);
      cashEUR += execQty * price;
      if (current.qty <= 1e-9) posMap.delete(symbol);
      else posMap.set(symbol, current);
    }
  }

  const positions = [];
  const sectorTotals = {};
  let equityEUR = 0;

  for (const current of posMap.values()) {
    const lastPrice = toNum(priceMap[current.symbol], current.lastPrice ?? current.avgCost ?? 0);
    const marketValue = current.qty * lastPrice;
    const unrealizedPnL = (lastPrice - current.avgCost) * current.qty;
    equityEUR += marketValue;
    const sector = current.sector || "UNKNOWN";
    sectorTotals[sector] = (sectorTotals[sector] || 0) + marketValue;
    positions.push({
      symbol: current.symbol,
      ts,
      qty: current.qty,
      avg_cost: roundTo(current.avgCost, 8),
      last_price: roundTo(lastPrice, 8),
      market_value_eur: roundTo(marketValue, 2),
      unrealized_pnl_eur: roundTo(unrealizedPnL, 2),
      weight_pct: 0,
    });
  }

  const totalValueEUR = cashEUR + equityEUR;
  for (const position of positions) {
    position.weight_pct = totalValueEUR > 0 ? position.market_value_eur / totalValueEUR : 0;
  }

  const initialCapitalEUR = toNum(meta?.initialCapitalEUR, 50000);
  const cumFeesEUR = toNum(meta?.cumFeesEUR, 0);
  const cumAiCostEUR = toNum(meta?.cumAiCostEUR, 0);
  const totalPnLEUR = totalValueEUR - initialCapitalEUR;
  const roi = initialCapitalEUR > 0 ? (totalPnLEUR / initialCapitalEUR) : 0;
  const cashPct = totalValueEUR > 0 ? (cashEUR / totalValueEUR) : 0;
  const top1PosPct = positions.length
    ? Math.max(...positions.map((p) => Number(p.market_value_eur) || 0)) / (totalValueEUR || 1)
    : 0;
  const top1SectorPct = Object.keys(sectorTotals).length
    ? Math.max(...Object.values(sectorTotals)) / (totalValueEUR || 1)
    : 0;
  const riskStatus = inferRiskStatus(cashPct, cashEUR);

  return {
    positions,
    portfolio: {
      ts,
      cash_eur: roundTo(cashEUR, 2),
      equity_eur: roundTo(equityEUR, 2),
      total_value_eur: roundTo(totalValueEUR, 2),
      cum_fees_eur: roundTo(cumFeesEUR, 2),
      cum_ai_cost_eur: roundTo(cumAiCostEUR, 2),
      trades_this_run: orders.length,
      total_pnl_eur: roundTo(totalPnLEUR, 2),
      roi,
      drawdown_pct: 0,
      meta_json: {
        source: "node8_portfolio_summary",
        start_cash_eur: roundTo(startCash, 2),
      },
    },
    risk: {
      ts,
      cash_pct: cashPct,
      top1_pos_pct: top1PosPct,
      top1_sector_pct: top1SectorPct,
      var95_est_eur: roundTo(equityEUR * 0.015 * 1.65, 2),
      positions_count: positions.length,
      risk_status: riskStatus,
      limits_json: {
        source: "node8_portfolio_summary",
      },
    },
  };
}

const input = $json || {};
const ctx = input.ctx || {};
const runCtx = ctx.run || {};
const meta = input.meta || ctx.meta || {};
const agentDecision = input.agentDecision || {};
const ordersIn = Array.isArray(input.orders) ? input.orders : [];
const warnings = Array.isArray(input.warnings) ? input.warnings : [];
const ts_end = new Date().toISOString();
const run_id = runCtx.runId || `RUN_${Date.now()}`;
const db_path = normalizeDbPath(input.db_path || runCtx.db_path || "");

// IMPORTANT: portfolio is in ctx (from node 7)
const portfolioSummary = input.portfolioSummary || ctx.portfolioSummary || { positions: [] };

// --- PRICE MAP ---
const priceMap = {};
if (Array.isArray(portfolioSummary.positions)) {
  portfolioSummary.positions.forEach((p) => {
    const sym = String(p.Symbol ?? "").trim();
    const px = Number(p.LastPrice);
    if (sym && Number.isFinite(px) && px > 0) priceMap[sym] = px;
  });
}

// complete with limit prices from actions/orders
if (Array.isArray(agentDecision.actions)) {
  agentDecision.actions.forEach((a) => {
    const sym = String(a.symbol_internal || a.symbol || "").trim();
    const lp = Number(a.entryPlan?.limitPrice);
    if (sym && !(sym in priceMap) && Number.isFinite(lp) && lp > 0) priceMap[sym] = lp;
  });
}

ordersIn.forEach((o) => {
  const sym = String(o.symbol || "").trim();
  const lp = Number(o.limitPrice);
  if (sym && !(sym in priceMap) && Number.isFinite(lp) && lp > 0) priceMap[sym] = lp;
});

const ai_signals = [];
if (Array.isArray(agentDecision.actions)) {
  agentDecision.actions.forEach((a, i) => {
    const symbol = String(a.symbol_internal || a.symbol || "").trim();
    if (!symbol || symbol === "CASH_EUR") return;
    const confidence = toNum(a.confidence, null);
    const signal = mapActionToSignal(a.action);
    const horizonDays = toNum(a.horizonDays, null);
    ai_signals.push({
      signal_id: `SIG_${run_id}_${i}`,
      ts: ts_end,
      symbol,
      signal,
      confidence: confidence == null ? null : Math.max(0, Math.min(100, Math.round(confidence))),
      horizon: Number.isFinite(horizonDays) ? `D${Math.max(1, Math.round(horizonDays))}` : null,
      entry_zone: clampText(a.entryPlan?.orderType || "", 32) || null,
      stop_loss: toNum(a.riskPlan?.stopLossPct, null),
      take_profit: toNum(a.riskPlan?.takeProfitPct, null),
      risk_score: confidence == null ? null : Math.max(0, Math.min(100, 100 - Math.round(confidence))),
      catalyst: null,
      rationale: clampText(a.rationale, 2048) || null,
      payload_json: a,
    });
  });
}

const alerts = [];
warnings.forEach((w, i) => {
  const msg = clampText(w, 2048);
  if (!msg) return;
  alerts.push({
    alert_id: `ALT_${run_id}_${i}`,
    ts: ts_end,
    severity: "WARN",
    category: "AGENT",
    symbol: extractSymbolFromText(msg),
    message: msg,
    code: "AGENT_WARNING",
    payload_json: { warning: String(w) },
  });
});

if (String(input.decision || "").toUpperCase() === "NO_TRADE" && warnings.length === 0) {
  alerts.push({
    alert_id: `ALT_${run_id}_NOTRADE`,
    ts: ts_end,
    severity: "INFO",
    category: "EXECUTION",
    symbol: "GLOBAL",
    message: "No executable orders for this run",
    code: "NO_TRADE",
    payload_json: { decision: input.decision || "NO_TRADE" },
  });
}

const snapshots = buildSnapshotsFromPortfolio(portfolioSummary, ordersIn, priceMap, ts_end, meta);

const bundle = {
  run: {
    run_id,
    ts_start: runCtx.timestampParis || ts_end,
    ts_end,
    tz: "Europe/Paris",
    model: runCtx.model || "UNKNOWN",
    db_path: db_path || null,
    decision_summary: input.decision || "NO_TRADE",
    agent_output_json: agentDecision,
    warnings_json: warnings,
  },
  orders: ordersIn.map((o, i) => ({
    order_id: `ORD_${run_id}_${i}`,
    symbol: o.symbol,
    side: o.side,
    order_type: normalizeOrderType(o.orderType),
    qty: o.quantity,
    limit_price: o.limitPrice ?? null,
  })),
  fills: ordersIn.map((o, i) => {
    const sym = String(o.symbol || "").trim();
    const orderType = normalizeOrderType(o.orderType);
    const px =
      (orderType === "LIMIT" && o.limitPrice) ? Number(o.limitPrice) :
      (priceMap[sym] ? Number(priceMap[sym]) : null);

    return {
      fill_id: `FIL_${run_id}_${i}`,
      order_id: `ORD_${run_id}_${i}`,
      symbol: sym,
      side: o.side,
      qty: o.quantity,
      price: (Number.isFinite(px) && px > 0) ? px : 1.0,
    };
  }),
  cash_ledger: [],
  market_prices: Object.entries(priceMap).map(([sym, px]) => ({ symbol: sym, close: px })),
  ai_signals,
  alerts,
  snapshots,
};

return [{
  json: {
    run_id,
    db_path,
    bundle,
    summary: {
      decision: input.decision,
      orders: ordersIn.length,
      fills: bundle.fills.length,
      ai_signals: ai_signals.length,
      alerts: alerts.length,
    }
  }
}];

