            lines.append(
                f"- {sym} | action={idea.get('action')} | targetQty={fmt_num(idea.get('targetQty'))}"
            )
            if idea.get("rationale"):
                lines.append(f"  rationale: {str(idea.get('rationale')).strip()}")
            count += 1

    return "\n".join(lines)


