                "lookbackDays": lookback_days,
                "_sectorFieldSource": sector_field_source,
            }
        }
    )

if not out:
    return [
        {
            "json": {
                "publishedAt": "",
                "ImpactScore": 0,
                "sectors_bullish": "",
                "sectors_bearish": "",
                "Winners": "",
                "Losers": "",
                "lookbackDays": lookback_days,
                "_sectorFieldSource": "none",
                "_emptyNews": True,
            }
        }
    ]

return out

